        if collapsible == 'open':
            attributes['open'] = 'open'
    self.body.append(
        self.starttag(node, tag_name, CLASS=f'admonition {name}', **attributes)
    )
    self.context.append(f'</{tag_name}>\n')
    if name:
        node.insert(0, nodes.title(name, admonitionlabels[name]))

