    if 'heading-level' in node:
        level = node['heading-level']
        try:
            tag = self.sectionnames[self.top_sectionlevel - 1 + level]
        except Exception:
            logger.warning(
                __('unsupported rubric heading level: %s'),
                level,
                type='latex',
                location=node,
            )

    self.body.append(rf'\{tag}*{{')
    self.context.append('}' + CR)
